// xorshift rng
struct R(u64);
impl R { fn n(&mut self)->u64{ let mut x=self.0; x^=x<<13; x^=x>>7; x^=x<<17; self.0=x; x } }

fn main(){
    let args: Vec<String> = std::env::args().collect();
    let seed: u64 = args.get(1).map(|s| s.parse().unwrap()).unwrap_or(12345);
    let iters: usize = args.get(2).map(|s| s.parse().unwrap()).unwrap_or(200000);
    let mode: u32 = args.get(3).map(|s| s.parse().unwrap()).unwrap_or(0);
    let mut r = R(seed);
    let mut found = 0;
    for _ in 0..iters {
        let len = (r.n() % 63 + 1) as usize; // 1..=63 bytes
        let mut v = Vec::with_capacity(len);
        for _ in 0..len {
            let b = match mode {
                0 => (r.n() % 255 + 1) as u8,          // any nonzero byte
                1 => {                                  // ASCII printable + specials
                    let t = b"abcXY019-._~:/?#[]@!$&'()*+,;=% \t\r\n\\\"<>{}|^`";
                    t[(r.n() as usize) % t.len()]
                }
                2 => (0x80 + (r.n() % 128)) as u8,      // high bytes only
                _ => (r.n() % 255 + 1) as u8,
            };
            v.push(b);
        }
        let out = run(&v);
        if out.as_bytes().get(1) != Some(&b'1') {
            println!("COUNTEREXAMPLE len={} out={} hex={}", v.len(), out,
                v.iter().map(|b| format!("{:02x}",b)).collect::<Vec<_>>().join(""));
            found += 1;
            if found > 20 { break; }
        }
    }
    println!("done mode={} iters={} counterexamples={}", mode, iters, found);
}
