use std::os::unix::ffi::OsStrExt;
use std::ffi::OsStr;
use std::process::Command;

fn run(b: &[u8]) -> String {
    let o = Command::new("/workspace/dataset/test4_executable")
        .arg(OsStr::from_bytes(b)).output().unwrap();
    String::from_utf8_lossy(&o.stdout).replace('\n', "")
}
fn hex(v:&[u8])->String{ v.iter().map(|b| format!("{:02x}",b)).collect::<Vec<_>>().join("") }

struct R(u64);
impl R { fn n(&mut self)->u64{ let mut x=self.0; x^=x<<13; x^=x>>7; x^=x<<17; self.0=x; x } }

fn check(v:&[u8], found:&mut u32){
    let out = run(v);
    let expect = if v.len()>=1 && v.len()<=63 { b'1' } else { b'0' };
    if out.as_bytes().get(1) != Some(&expect) {
        println!("COUNTEREXAMPLE len={} out={} hex={} expected_line2={}",
            v.len(), out, hex(v), expect as char);
        *found+=1;
    }
}

fn main(){
    let a: Vec<String> = std::env::args().collect();
    let mode: u32 = a[1].parse().unwrap();
    let mut found=0u32;
    let mut n=0u64;
    match mode {
        // exhaustive all 2-byte inputs (no NUL)
        3 => { for x in 1..=255u8 { for y in 1..=255u8 { check(&[x,y], &mut found); n+=1; } } }
        // positional substitution: base 'a'*63, replace each position with every byte
        4 => { for p in 0..63 { for b in 1..=255u8 { let mut v=vec![b'a';63]; v[p]=b; check(&v,&mut found); n+=1; } } }
        // lengths 64..400 of assorted content -> must all be line2=0
        5 => { let pats: Vec<&[u8]> = vec![b"a", b"-", b".", b"_", b"\xe4\xbe\x8b", b"xn--", b"\xff", b" "];
               for p in pats { for len in 1..=400usize {
                   let mut v=Vec::new(); while v.len()<len { v.push(p[v.len()%p.len()]); }
                   check(&v,&mut found); n+=1; } } }
        // random len 0..300, verify the full predicate both directions
        6 => { let mut r=R(4242); for _ in 0..40000 { let len=(r.n()%301) as usize;
                   let mut v=Vec::new(); for _ in 0..len { v.push((r.n()%255+1) as u8); }
                   check(&v,&mut found); n+=1; } }
        // exhaustive 3-byte over interesting alphabet
        7 => { let al = b"a-._ 0xX*:/\xff\x80\xe4\x7f\x01A";
               for &x in al { for &y in al { for &z in al { check(&[x,y,z], &mut found); n+=1; } } } }
        _=>{}
    }
    println!("done mode={} tested={} counterexamples={}", mode, n, found);
}
