  let add=|c:&mut Vec<(String,Vec<u8>)>, n:&str, v:Vec<u8>| c.push((n.to_string(),v));
  // truncated multibyte exactly at 63-byte boundary
  for (name, tail) in [("trunc2B",vec![0xC3u8]),("trunc3B_1",vec![0xE4]),("trunc3B_2",vec![0xE4,0xBE]),
                       ("trunc4B_1",vec![0xF0]),("trunc4B_2",vec![0xF0,0x9F]),("trunc4B_3",vec![0xF0,0x9F,0x98])]{
    for len in [62usize,63,64] {
      if len < tail.len() { continue }
      let mut v=vec![b'a'; len-tail.len()]; v.extend_from_slice(&tail);
      add(&mut cases,&format!("{}@{}B",name,len),v);
    }
  }
  add(&mut cases,"overlong_slash",vec![0xC0,0xAF]);
  add(&mut cases,"overlong_NUL",vec![0xC0,0x80]);
  add(&mut cases,"overlong_dot",vec![0xC0,0xAE]);
  add(&mut cases,"surrogate_D800",vec![0xED,0xA0,0x80]);
  add(&mut cases,"surrogate_DFFF",vec![0xED,0xBF,0xBF]);
  add(&mut cases,"U+FFFE",vec![0xEF,0xBF,0xBE]);
  add(&mut cases,"U+FFFF",vec![0xEF,0xBF,0xBF]);
  add(&mut cases,"BOM",vec![0xEF,0xBB,0xBF]);
  add(&mut cases,"U+10FFFF",vec![0xF4,0x8F,0xBF,0xBF]);
  add(&mut cases,"beyond_U+10FFFF",vec![0xF4,0x90,0x80,0x80]);
  add(&mut cases,"lead_F5",vec![0xF5,0x80,0x80,0x80]);
  add(&mut cases,"lead_FE",vec![0xFE]);
  add(&mut cases,"lead_FF",vec![0xFF]);
  add(&mut cases,"5byte_FB",vec![0xFB,0x80,0x80,0x80,0x80]);
  add(&mut cases,"6byte_FD",vec![0xFD,0x80,0x80,0x80,0x80,0x80]);
  add(&mut cases,"lone_cont_80",vec![0x80]);
  add(&mut cases,"lone_cont_BF",vec![0xBF]);
  add(&mut cases,"DEL_7F",vec![0x7F]);
  add(&mut cases,"BOM+dot",vec![0xEF,0xBB,0xBF,b'.']);
  // 63 bytes of pure 0xFF / 0x80
  add(&mut cases,"63xFF",vec![0xFFu8;63]); add(&mut cases,"64xFF",vec![0xFFu8;64]);
  add(&mut cases,"63x80",vec![0x80u8;63]); add(&mut cases,"64x80",vec![0x80u8;64]);
  add(&mut cases,"63xC0",vec![0xC0u8;63]); add(&mut cases,"64xC0",vec![0xC0u8;64]);
  let mut bad=0;
  for (n,v) in &cases {
    let out=run(v);
    let exp = if v.len()>=1 && v.len()<=63 {'1'} else {'0'};
    let got = out.chars().nth(1).unwrap();
    let flag = if got!=exp {bad+=1; " <== COUNTEREXAMPLE"} else {""};
    println!("{:<18} len={:<3} out={} hex={}{}", n, v.len(), out, hex(v), flag);
  }
  println!("counterexamples={}", bad);
}
